// The type of nodata.c, generated by tools/make_nodata_font.py from the website's fonts
// (site/fonts: Libre Caslon Display, Crimson Pro and VT323, SIL Open Font License 1.1, see
// site/fonts/OFL-*.txt). ASCII 32..126 per style; coverage 4 bits a pixel, low nibble first.
#pragma once

#define ND_FIRST 32
#define ND_LAST 126
#define ND_SUB 8   // advances and kerning in 1/8 pixel

enum {
	ND_LABEL,  // vt323-400 15 px: labels, letterspaced capitals
	ND_MONO,   // vt323-400 20 px: paths, addresses, step numbers
	ND_TITLE,  // libre-caslon-display-400 32 px: the heading, capitals
	ND_BODY,   // crimson-pro 16 px: text
	ND_ITALIC, // crimson-pro-italic 17 px: the lede under the heading
	ND_STYLES
};

typedef struct {
	unsigned int off;          // into nd_bits
	unsigned char w, h;        // the coverage box
	signed char x, y;          // its top left from the pen on the baseline
	unsigned short adv;        // in 1/ND_SUB pixel
} NdGlyph;

typedef struct { unsigned char a, b; signed char k; } NdKern;   // k in 1/ND_SUB pixel

typedef struct {
	const NdGlyph* glyph;      // ND_FIRST..ND_LAST
	const NdKern* kern;
	int nkern;
	int ascent, descent;
} NdFont;

